contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: try to call transfer and assert the relation between revert flag and return
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty recipients to match contract's require, otherwise C.transfer would revert by its own precondition
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        // perform the call and capture whether it reverted
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: C.transfer either returns true (and did not revert) or it reverts; it cannot return false.
        // Additionally, if it returned true then reverted==false. If it reverted then it did not return true.
        // Expressed as: returned true iff not reverted.
        assert(ret == (!reverted));
    }

    receive() external payable {}
}

